<?php
declare(strict_types=1); namespace Wms;
abstract class Service {public function __construct(protected Database $db,protected Audit $audit){} protected function conflict(int $changed):void{if($changed!==1)throw new ApiException('CONFLICT','Данные были изменены другим пользователем. Информация обновлена. Повторите действие.',409);} protected function one(string $sql,array $p=[],string $message='Запись не найдена'):array{$r=$this->db->one($sql,$p);if(!$r)throw new ApiException('NOT_FOUND',$message,404);return$r;} protected function camel(array $r):array{$out=[];foreach($r as$k=>$v){$out[preg_replace_callback('/_([a-z])/',fn($m)=>strtoupper($m[1]),$k)]=$v;}return$out;} protected function paged(string $from,array$p,string $where='1=1',array$args=[],string$order='created_at DESC'):array{[$page,$size,$offset]=Util::page($p);$search=Util::text($p['search']??'');if($search!==''){$where.=' AND search_text LIKE ?';$args[]='%'.$search.'%';}$total=(int)$this->db->one("SELECT COUNT(*) n FROM $from WHERE $where",$args)['n'];$args[]=$size;$args[]=$offset;$rows=$this->db->all("SELECT * FROM $from WHERE $where ORDER BY $order LIMIT ? OFFSET ?",$args);return['items'=>array_map(fn($r)=>$this->camel($r),$rows),'page'=>$page,'pageSize'=>$size,'total'=>$total,'pages'=>(int)ceil($total/$size)];}}
